<template>
 <main class="shipyard-admin">
  <header class="workspace-header"><div><p class="eyebrow">船厂工程管理</p><h1>{{activeLabel}}</h1><p class="subtitle">{{data.user.name || '工作账号'}} · {{data.serverDate}} <span v-if="updated">数据更新于 {{updated}}</span></p></div><div class="workspace-controls"><el-select v-model="projectId" aria-label="当前工程" placeholder="选择工程"><el-option v-for="p in data.projects" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-button :loading="loading" @click="act(refreshPage)">刷新数据</el-button></div></header>
  <nav class="workspace-nav" aria-label="船厂业务导航"><button v-for="tab in tabs" :key="tab.id" :class="{active:section===tab.id}" @click="navigate(tab.id)">{{tab.label}}</button></nav>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon><el-button link @click="act(refresh)">重新加载</el-button></el-alert>
  <el-skeleton v-if="!ready && loading" :rows="8" animated/>
  <el-empty v-else-if="!ready" description="工作数据尚未加载，请重试"/>
  <template v-else>
   <section v-if="section==='workbench'">
    <div class="table-heading"><h2>待处理事项</h2><div class="actions"><el-button v-if="can('work:submit')" type="primary" @click="newRecord('用工')">新增用工</el-button><el-button v-if="can('expense:submit')" @click="newRecord('报销')">申请报销</el-button><el-button v-if="can('fine:submit')" @click="newRecord('罚款')">登记罚款</el-button></div></div>
    <p class="hint">{{tasks.length}} 项待处理。审批、付款和收款结果会同步到小程序与 H5。</p>
    <el-table :data="tasks" empty-text="当前工程暂无待处理事项" @row-click="openTask"><el-table-column prop="title" label="事项"/><el-table-column prop="author" label="申请人" width="140"/><el-table-column prop="date" label="日期" width="140"/><el-table-column prop="status" label="当前状态"/><el-table-column label="金额"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click.stop="openTask(row)">{{row.taskType==='area'?'前往确认':row.taskType==='reversal'?'前往审批':'查看处理'}}</el-button></template></el-table-column></el-table>
    <template v-if="can('finance:view')"><div class="table-heading"><h2>工程经营情况</h2><span class="hint">包含已审批未付款成本</span></div><el-descriptions :column="3" border><el-descriptions-item label="合同总额">¥{{money(project?.price)}}</el-descriptions-item><el-descriptions-item label="已审批工资">¥{{money(project?.wages)}}</el-descriptions-item><el-descriptions-item label="两级已审批报销">¥{{money(project?.reimbursements)}}</el-descriptions-item><el-descriptions-item label="其他支出">¥{{money(project?.otherCosts)}}</el-descriptions-item><el-descriptions-item label="预计毛利">¥{{money((project?.price||0)-(project?.wages||0)-(project?.reimbursements||0)-(project?.otherCosts||0))}}</el-descriptions-item><el-descriptions-item label="实际资金余额">¥{{money(scoped(data.transactions).reduce((s,t)=>s+t.amount,0))}}</el-descriptions-item></el-descriptions><el-collapse class="unpaid-costs"><el-collapse-item name="unpaid"><template #title><span class="unpaid-title">已审批未付成本 ¥{{money(unpaidTotal)}} · {{unpaidCosts.length}} 项</span></template><el-table :data="unpaidCosts" size="small" empty-text="暂无已审批未付成本" @row-click="row=>row.record&&showRecord(row.record)"><el-table-column prop="type" label="类型" width="90"/><el-table-column prop="title" label="事项" min-width="220"/><el-table-column prop="date" label="日期/月份" width="120"/><el-table-column label="金额" width="140"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column></el-table></el-collapse-item></el-collapse></template>
   <MonthlyPayroll v-if="can('finance:view') || can('payroll:pay')" :data="data"/>
   </section>
   <section v-else-if="section==='projects'">
    <div class="table-heading"><h2>工程与工作区域</h2><el-button v-if="can('master:edit')" type="primary" @click="editMaster('project')">新增工程</el-button></div>
    <el-table :data="data.projects"><el-table-column prop="name" label="船号"/><el-table-column prop="title" label="工程名称"/><el-table-column label="合同总价"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column><el-table-column prop="area" label="面积 m²"/><el-table-column label="加班计薪"><template #default>同正常时薪</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="projectId=row.id">查看区域</el-button><el-button v-if="can('master:edit')" link type="primary" @click="editMaster('project',row)">编辑工程</el-button></template></el-table-column></el-table>
    <div class="table-heading"><h2>{{project?.name}} · 工作区域</h2><el-button v-if="can('master:edit') && project" @click="editMaster('area')">新增区域</el-button></div>
    <el-table :data="scoped(data.areas)"><el-table-column prop="name" label="区域" min-width="130"/><el-table-column prop="area" label="面积 m²"/><el-table-column prop="rate" label="结算单价"/><el-table-column label="负责组长" min-width="100"><template #default="{row}">{{row.leaderId?(row.leader||'—'):'不指定'}}</template></el-table-column><el-table-column prop="people" label="安排人数"/><el-table-column label="施工人员" min-width="160"><template #default="{row}">{{(row.workers||[]).map(w=>w.name).join('、')||'—'}}</template></el-table-column><el-table-column label="施工方式" min-width="90"><template #default="{row}">{{workType(row)}}</template></el-table-column><el-table-column label="包工" min-width="110"><template #default="{row}">¥{{money(row.contract)}}</template></el-table-column><el-table-column label="点工" min-width="110"><template #default="{row}">¥{{money(row.hourly)}}</template></el-table-column><el-table-column label="加班" min-width="110"><template #default="{row}">¥{{money(row.overtime)}}</template></el-table-column><el-table-column label="合计" min-width="120"><template #default="{row}">¥{{money(areaTotal(row))}}</template></el-table-column><el-table-column label="施工状态" min-width="150"><template #default="{row}">{{row.status}}<div v-if="row.completionRequestedAt&&!row.completedAt" class="hint">{{row.completionRequester||'组长'}} · {{row.completionRequestedAt}}</div></template></el-table-column><el-table-column label="操作" min-width="220"><template #default="{row}"><el-button v-if="can('master:edit')&&!row.completedAt" link @click="editMaster('area',row)">编辑区域</el-button><el-button v-if="canRequestCompletion(row)" link :disabled="busy" @click="requestCompletion(row)">提交完工</el-button><el-button v-if="can('work:complete')&&row.completionRequestedAt&&!row.completedAt" link :disabled="busy" @click="rejectCompletion(row)">退回完工</el-button><el-button v-if="canConfirmCompletion(row)" link type="primary" :disabled="busy" @click="complete(row)">确认完工</el-button><el-button v-if="can('work:complete')&&row.completedAt" link type="warning" :disabled="busy" @click="reopen(row)">重新开工</el-button></template></el-table-column></el-table>
    <div class="crew-management"><div class="table-heading"><h2>具体班组</h2><el-button v-if="can('master:edit')" @click="editMaster('crew')">新增班组</el-button></div><el-table :data="data.crews" empty-text="尚未建立具体班组"><el-table-column label="班组"><template #default="{row}">{{crewLabel(row)}}</template></el-table-column><el-table-column label="类型"><template #default="{row}">{{teamLabel(row.category)}}</template></el-table-column><el-table-column label="在职人员"><template #default="{row}">{{data.people.filter(p=>p.crewId===row.id).length}} 人</template></el-table-column><el-table-column label="组长状态"><template #default="{row}">{{Number(row.leaderActive)?'正常':'请重新指定组长'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="can('master:edit')" link type="primary" @click="editMaster('crew',row)">编辑班组</el-button></template></el-table-column></el-table></div>
    <div class="table-heading"><h2>工人与时薪</h2><el-button v-if="can('master:edit')" @click="editMaster('person')">新增人员</el-button></div><TeamSelect v-model="personTeamFilter" label="人员班组筛选" filter /><CrewSelect v-model="personCrewFilter" :crews="data.crews" label="具体班组筛选" filter /><el-input v-model="personSearch" placeholder="搜索姓名、工号、班组" clearable class="search" aria-label="搜索人员"/><el-table :data="people"><el-table-column prop="name" label="姓名"/><el-table-column prop="code" label="工号"/><el-table-column label="班组" min-width="190"><template #default="{row}">{{workerCrewLabel(row,data.crews)}}</template></el-table-column><el-table-column label="班组分类"><template #default="{row}">{{teamLabel(row.teamCategory)}}</template></el-table-column><el-table-column prop="rate" label="小时工资"/><el-table-column label="状态"><template #default="{row}">{{Number(row.active ?? 1)===1?'在职':'已停用'}}</template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{row}"><template v-if="can('master:edit')"><el-button link type="primary" @click="editMaster('person',row)">编辑人员</el-button><el-button link :type="Number(row.active ?? 1)===1?'danger':'primary'" :disabled="busy" @click="toggleWorker(row)">{{Number(row.active ?? 1)===1?'停用人员':'恢复人员'}}</el-button></template></template></el-table-column></el-table>
   </section>
   <section v-else-if="section==='records'">
    <div class="table-heading"><h2>业务申请与审批</h2><div class="actions"><el-button v-if="can('work:submit')" type="primary" @click="newRecord('用工')">新增用工</el-button><el-button v-if="can('expense:submit')" @click="newRecord('报销')">申请报销</el-button><el-button v-if="can('fine:submit')" @click="newRecord('罚款')">登记罚款</el-button><el-button @click="exportRecords">导出申请</el-button></div></div>
    <div class="filters"><el-input v-model="search" placeholder="搜索单号、说明、申请人" clearable aria-label="搜索申请"/><el-select v-model="kind" aria-label="申请类型"><el-option label="全部类型" value=""/><el-option v-for="k in ['用工','报销','罚款']" :key="k" :label="k" :value="k"/></el-select><el-select v-model="recordAreaId" aria-label="工作区域筛选"><el-option label="全部区域" value=""/><el-option v-for="area in scoped(data.areas)" :key="area.id" :label="area.name" :value="area.id"/></el-select><el-select v-model="status" aria-label="申请状态"><el-option label="全部状态" value=""/><el-option v-for="s in statuses" :key="s" :label="s" :value="s"/></el-select><el-select v-model="recordMonthBy" aria-label="月份口径"><el-option label="按业务月份" value="business"/><el-option label="按付款月份" value="paid"/></el-select><el-date-picker v-model="recordMonth" type="month" value-format="YYYY-MM" clearable placeholder="全部月份" aria-label="申请月份"/></div>
    <el-table :data="records" row-key="id"><el-table-column prop="title" label="申请" min-width="140"/><el-table-column prop="area" label="区域" min-width="150"/><el-table-column prop="author" label="申请人" width="110"/><el-table-column prop="date" label="日期" width="125"/><el-table-column prop="note" label="说明" min-width="180" show-overflow-tooltip/><el-table-column label="金额" width="130"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column prop="status" label="状态" min-width="140"/><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showRecord(row)">查看详情</el-button></template></el-table-column></el-table>
   </section>
   <section v-else-if="section==='attendance'">
    <div class="table-heading"><h2>区域每日出勤</h2><el-button @click="exportAttendance">导出出勤</el-button></div><el-date-picker v-model="attendanceDate" value-format="YYYY-MM-DD" aria-label="出勤日期" placeholder="选择日期"/><p class="hint">按已审批的点工及加班记录统计，{{attendanceWorkers}} 人出勤。同一人不同区域分别列示。</p>
    <el-table :data="attendance"><el-table-column label="区域"><template #default="{row}">{{data.areas.find(a=>String(a.id)===String(row.areaId))?.name}}</template></el-table-column><el-table-column prop="name" label="工人"/><el-table-column prop="code" label="工号"/><el-table-column prop="team" label="班组"/><el-table-column prop="hours" label="工时（含加班）"/></el-table>
   </section>
   <section v-else-if="section==='archive'">
    <div class="table-heading"><h2>{{archiveRange==='all'?'全部完工归档':'近三个月完工归档'}}</h2><div class="actions"><el-radio-group v-model="archiveRange" aria-label="归档范围"><el-radio-button value="recent">近三个月</el-radio-button><el-radio-button value="all">全部历史</el-radio-button></el-radio-group><el-date-picker v-model="archiveMonth" type="month" value-format="YYYY-MM" :placeholder="archiveRange==='all'?'全部月份':'全部近三个月'" clearable aria-label="归档月份"/></div></div>
    <el-table :data="archives"><el-table-column prop="name" label="工作区域" min-width="130"/><el-table-column prop="completedAt" label="完工时间" min-width="150"/><el-table-column label="施工方式"><template #default="{row}">{{workType(row)}}</template></el-table-column><el-table-column label="包工"><template #default="{row}">¥{{money(row.contract)}}</template></el-table-column><el-table-column label="点工"><template #default="{row}">¥{{money(row.hourly)}}</template></el-table-column><el-table-column label="加班"><template #default="{row}">¥{{money(row.overtime)}}</template></el-table-column><el-table-column label="合计"><template #default="{row}">¥{{money(areaTotal(row))}}</template></el-table-column><el-table-column label="工资结算"><template #default="{row}">{{row.paid?'已结清':'待结算'}}</template></el-table-column><el-table-column label="操作" min-width="190"><template #default="{row}"><el-button link @click="recordAreaId=row.id;search='';kind='用工';status='';recordMonth='';navigate('records')">查看施工记录</el-button><el-button v-if="can('work:complete')" link type="warning" :disabled="busy" @click="reopen(row)">重新开工</el-button></template></el-table-column></el-table><p class="hint">完工不等于结清，历史单据仍保留在申请记录中。</p>
   </section>
   <section v-else-if="section==='payroll'">
    <div class="table-heading"><h2>工资结算</h2><el-button @click="exportPayroll">导出工资明细</el-button></div><div class="filters"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" aria-label="工资月份"/><span>选择合计 <strong>¥{{money(selectedTotal)}}</strong> · <span data-field="selectedWorkers">{{selectedWorkers}} 人</span> · <span data-field="selectedLines">{{selectedLines.length}} 条</span></span><el-button v-if="can('payroll:pay')" type="primary" :loading="busy" :disabled="!selected.length || !!error" @click="settle">确认工资结算</el-button></div>
    <el-table ref="payrollTable" :data="payroll" row-key="id" @selection-change="selected=$event"><el-table-column type="selection" width="45" :reserve-selection="true" :selectable="row=>!row.paid"/><el-table-column prop="name" label="工人"/><el-table-column label="工作地点" min-width="210"><template #default="{row}">{{row.ship || '未记录船号'}} · {{row.area || '未记录工作区域'}}</template></el-table-column><el-table-column prop="label" label="类型"/><el-table-column prop="hours" label="工时"/><el-table-column prop="rate" label="时薪快照"/><el-table-column prop="multiplier" label="倍率"/><el-table-column label="金额"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.paid?'已结算':'待结算'}}</template></el-table-column><el-table-column label="支付信息" min-width="170"><template #default="{row}">{{row.paid&&batchOf(row)?batchOf(row).paidDate+' · '+batchOf(row).method:'—'}}</template></el-table-column></el-table>
   </section>
   <section v-else-if="section==='ledger'">
    <p v-if="!can('finance:view') && !can('payroll:pay')" class="hint">仅显示本人登记的其他收支，余额不代表整个工程。</p>
    <div class="table-heading"><h2>收支台账</h2><div class="actions"><el-button v-if="can('ledger:edit')" type="primary" @click="openLedger">登记收支</el-button><el-button v-if="can('ledger:edit')" :disabled="hasOpening" :title="hasOpening?'该工程已登记期初余额，如需更正请申请冲正':''" @click="openOpening">登记期初余额</el-button><el-button @click="exportLedger">导出台账</el-button></div></div><div class="filters"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" aria-label="台账月份"/><span>本月收入 ¥{{money(income)}} / 支出 ¥{{money(expense)}} / 截至本月余额 ¥{{money(balance)}}</span></div>
    <el-table :data="transactions" row-key="id"><el-table-column prop="date" label="日期" width="115"/><el-table-column label="收支事项" min-width="160"><template #default="{row}">{{ledgerTitle(row)}}</template></el-table-column><el-table-column label="收入" min-width="110"><template #default="{row}">{{row.amount>0?'¥'+money(row.amount):'—'}}</template></el-table-column><el-table-column label="支出" min-width="110"><template #default="{row}">{{row.amount<0?'¥'+money(-row.amount):'—'}}</template></el-table-column><el-table-column prop="note" label="备注" min-width="180" show-overflow-tooltip/><el-table-column label="登记人" width="100"><template #default="{row}">{{row.creator||'—'}}</template></el-table-column><el-table-column label="凭证" width="110"><template #default="{row}"><el-button v-if="voucherIds(row).length" link type="primary" @click="showVouchers(row)">查看凭证 {{voucherIds(row).length}}</el-button><span v-else>—</span></template></el-table-column><el-table-column label="冲正" min-width="200"><template #default="{row}"><template v-if="row.source==='reversal'">冲正流水</template><template v-else-if="row.reversal">{{reversalLabels[row.reversal.status]||row.reversal.status}}<div class="hint">{{row.reversal.requester}}：{{row.reversal.reason}}<template v-if="row.reversal.opinion"><br>{{row.reversal.reviewer}}：{{row.reversal.opinion}}</template></div></template><template v-else>—</template></template></el-table-column><el-table-column label="操作" min-width="150" fixed="right"><template #default="{row}"><el-button v-if="canRequestReversal(row)" link type="danger" :disabled="busy" @click="requestReversal(row)">申请冲正</el-button><template v-if="canReviewReversal(row)"><el-button link type="primary" :disabled="busy" @click="reviewReversal(row,true)">同意冲正</el-button><el-button link type="danger" :disabled="busy" @click="reviewReversal(row,false)">驳回冲正</el-button></template></template></el-table-column></el-table>
   </section>
   <Accounts ref="accountsPage" v-else-if="section==='accounts' && can('account:edit')" :projects="data.projects" :refresh="refresh"/>
   <section v-else-if="section==='notifications'"><div class="table-heading"><h2>审批与处理消息</h2><div class="actions"><span>已读状态在三端同步</span><el-button :disabled="busy || !data.notifications.some(n=>!n.read)" @click="markAllRead">全部已读</el-button></div></div><el-table :data="data.notifications"><el-table-column prop="title" label="消息"/><el-table-column prop="detail" label="说明"/><el-table-column prop="time" label="时间"/><el-table-column label="状态"><template #default="{row}">{{row.read?'已读':'未读'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="openNotice(row)">查看单据</el-button></template></el-table-column></el-table></section>
   <el-empty v-else description="当前账号没有此页面权限"/>
  </template>
  <RecordForm v-if="formKind" :key="formKind+(editRecord?.id||'new')" :kind="formKind" :data="data" :project-id="projectId" :record="editRecord" :write="write" @close="formKind=''" @saved="showRecord"/>
  <RecordDetail v-if="detail" :key="detail.id" :record="detail" :data="data" :can="can" :write="write" @close="detail=null" @edit="editApplication"/>
  <MasterEditor v-if="master" :type="master.type" :value="master.value" :crews="data.crews" :leaders="data.crewLeaders" :project-id="projectId" :write="write" @close="master=null"/>
  <el-drawer class="shipyard-dialog" v-model="ledgerOpen" title="登记其他收支" size="min(540px,96vw)"><el-form label-position="top"><el-form-item label="收支类型"><el-radio-group v-model="entry.direction"><el-radio value="收入">收入</el-radio><el-radio value="支出">支出</el-radio></el-radio-group></el-form-item><el-form-item label="事项名称"><el-input v-model="entry.title" aria-label="收支事项" maxlength="100"/></el-form-item><el-form-item label="金额"><el-input-number v-model="entry.amount" :min="0.01" :precision="2" aria-label="收支金额"/></el-form-item><el-form-item label="业务日期"><el-date-picker v-model="entry.date" value-format="YYYY-MM-DD" aria-label="收支日期"/></el-form-item><el-form-item label="备注"><el-input v-model="entry.note" type="textarea" maxlength="500" aria-label="收支备注"/></el-form-item><el-form-item label="收支凭证（必填，最多6张）"><input type="file" accept="image/png,image/jpeg" multiple aria-label="上传收支凭证" :disabled="busy||uploading" @change="addVouchers($event,entry.files)"/><p class="hint">每张不超过 5 MB。{{uploading?'上传中…':''}}</p><div v-for="(f,i) in entry.files" :key="f" class="file-line"><span>凭证 {{i+1}}</span><el-button link type="danger" @click="entry.files.splice(i,1)">移除</el-button></div><PrivateImages :ids="entry.files||[]"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" :disabled="uploading" @click="saveLedger">保存收支</el-button></template></el-drawer>
  <el-drawer class="shipyard-dialog" v-model="openingOpen" title="登记期初余额" size="min(540px,96vw)"><p class="hint">每个工程只能登记一次期初余额，登记后如需更正请申请冲正。</p><el-form label-position="top"><el-form-item label="期初方向"><el-radio-group v-model="opening.direction" aria-label="期初方向"><el-radio value="余额">余额</el-radio><el-radio value="透支">透支</el-radio></el-radio-group></el-form-item><el-form-item label="期初金额"><el-input-number v-model="opening.amount" :min="0.01" :precision="2" aria-label="期初金额"/><span class="hint">登记为 {{opening.direction==='透支'?'-':''}}¥{{money(opening.amount)}}</span></el-form-item><el-form-item label="期初日期"><el-date-picker v-model="opening.date" value-format="YYYY-MM-DD" :disabled-date="isFuture" :clearable="false" aria-label="期初日期"/></el-form-item><el-form-item label="备注"><el-input v-model="opening.note" type="textarea" maxlength="500" aria-label="期初备注"/></el-form-item><el-form-item label="凭证（选填，最多6张）"><input type="file" accept="image/png,image/jpeg" multiple aria-label="上传期初凭证" :disabled="busy||uploading" @change="addVouchers($event,opening.files)"/><div v-for="(f,i) in opening.files" :key="f" class="file-line"><span>凭证 {{i+1}}</span><el-button link type="danger" @click="opening.files.splice(i,1)">移除</el-button></div><PrivateImages :ids="opening.files||[]"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" :disabled="uploading" @click="saveOpening">保存期初余额</el-button></template></el-drawer>
  <el-drawer class="shipyard-dialog" v-model="settleOpen" title="登记工资支付" size="min(540px,96vw)"><p>{{project?.name}} · {{month}} · 已选 {{selectedWorkers}} 人 / {{selectedLines.length}} 条，合计 <strong>¥{{money(selectedTotal)}}</strong></p><el-form label-position="top"><el-form-item label="实际支付日期"><el-date-picker v-model="payment.date" value-format="YYYY-MM-DD" :disabled-date="isFuture" :clearable="false" aria-label="工资支付日期"/></el-form-item><el-form-item label="支付方式"><el-select v-model="payment.method" aria-label="工资支付方式"><el-option v-for="m in payMethods" :key="m" :label="m" :value="m"/></el-select></el-form-item><el-form-item label="支付凭证（必填）"><input type="file" accept="image/png,image/jpeg" aria-label="上传工资支付凭证" :disabled="busy||uploading" @change="uploadPayrollProof"/><PrivateImages :ids="payment.proof?[payment.proof]:[]"/></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="settleOpen=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!payment.proof||!selectedLines.length||uploading" @click="confirmSettle">确认已支付</el-button></template></el-drawer>
  <el-dialog v-model="voucherOpen" class="shipyard-dialog" title="收支凭证" width="min(720px,96vw)"><PrivateImages :ids="voucherList"/></el-dialog>
 </main>
</template>
<script setup>
import MonthlyPayroll from './components/MonthlyPayroll.vue'
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useShipyard} from './useShipyard'
import {money,exportCsv,requestKey,shipyardApi,uploadImage,payMethods,dayText} from '@/api/shipyard'
import PrivateImages from './components/PrivateImages.vue'
import RecordForm from './components/RecordForm.vue'
import RecordDetail from './components/RecordDetail.vue'
import MasterEditor from './components/MasterEditor.vue'
import Accounts from './components/Accounts.vue'
import TeamSelect from './components/TeamSelect.vue'
import CrewSelect from './components/CrewSelect.vue'
import {crewLabel,workerCrewLabel,matchesCrew,groupWorkers} from '@/utils/shipyard-crews'
import {teamLabel,matchesTeam} from '@/utils/shipyard-teams'
const {data,loading,ready,error,projectId,project,month,updated,busy,can,scoped,refresh,write,act}=useShipyard(),route=useRoute(),router=useRouter()
const section=computed(()=>route.params.section||'workbench')
const tabs=computed(()=>[
 {id:'workbench',label:'工作台'}, {id:'projects',label:'工程与人员'}, {id:'records',label:'申请与审批'},
 ...(can('finance:view')||can('payroll:pay')?[{id:'attendance',label:'每日出勤'},{id:'payroll',label:'工资结算'}]:[]),
 ...(can('finance:view')||can('payroll:pay')||can('ledger:edit')?[{id:'ledger',label:'收支台账'}]:[]),
 {id:'archive',label:'完工归档'},...(can('account:edit')?[{id:'accounts',label:'账号权限'}]:[]),{id:'notifications',label:'消息'}])
const activeLabel=computed(()=>tabs.value.find(t=>t.id===section.value)?.label||'船厂工作台')
watch([ready,tabs,section],()=>{if(ready.value&&!tabs.value.some(t=>t.id===section.value))navigate('workbench')})
function navigate(id){router.push('/shipyard/workspace/'+id)}
const formKind=ref(''),editRecord=ref(null),detail=ref(null),master=ref(null),personSearch=ref(''),search=ref(''),kind=ref(''),status=ref(''),recordMonth=ref(''),attendanceDate=ref(''),archiveMonth=ref(''),selected=ref([]),ledgerOpen=ref(false),entry=ref({}),payrollTable=ref(null),accountsPage=ref(null),recordAreaId=ref('')
const recordMonthBy=ref('business'),archiveRange=ref('recent'),openingOpen=ref(false),opening=ref({}),settleOpen=ref(false),payment=ref({}),voucherOpen=ref(false),voucherList=ref([]),uploading=ref(false)
const statuses=['待审批','待负责人签字','待结算','已结算','待付款','已付款','会计待处理','已处理','已退回','作废待确认','已作废']
const isFuture=d=>dayText(d)>data.serverDate
watch(()=>data.serverDate,date=>{if(!attendanceDate.value)attendanceDate.value=date})
watch([projectId,month,section],()=>{selected.value=[];payrollTable.value?.clearSelection()})
watch(projectId,()=>{recordAreaId.value=''})
watch(()=>data.grants,()=>{
 if(formKind.value&&!can(formKind.value==='用工'?'work:submit':formKind.value==='罚款'?'fine:submit':'expense:submit')){formKind.value='';editRecord.value=null}
 if(master.value&&!can('master:edit'))master.value=null
 if(ledgerOpen.value&&!can('ledger:edit'))ledgerOpen.value=false
 if(openingOpen.value&&!can('ledger:edit'))openingOpen.value=false
 if(settleOpen.value&&!can('payroll:pay'))settleOpen.value=false
},{deep:true})
const personTeamFilter=ref('all'),personCrewFilter=ref('all')
const people=computed(()=>groupWorkers((can('master:edit')?(data.workerArchive ?? data.people):data.people).filter(p=>matchesTeam(p,personTeamFilter.value)&&matchesCrew(p,personCrewFilter.value)&&[p.name,p.code,workerCrewLabel(p,data.crews),teamLabel(p.teamCategory)].join(' ').includes(personSearch.value)),data.crews).flatMap(g=>g.people))
const records=computed(()=>scoped(data.records).filter(r=>(!recordAreaId.value||Number(r.areaId)===Number(recordAreaId.value))&&(!kind.value||r.kind===kind.value)&&(!status.value||r.status===status.value)&&(!recordMonth.value||String((recordMonthBy.value==='paid'?r.paidDate:r.date)||'').startsWith(recordMonth.value))&&[r.id,r.note,r.author,r.area].join(' ').includes(search.value)))
const mine=id=>Number(id)===Number(data.user.id)
const approvePermission=kind=>kind==='用工'?'work:approve':kind==='罚款'?'fine:approve':'expense:approve'
function reviewable(r){if(mine(r.createdBy))return false;if(r.status==='待负责人签字')return can('expense:confirm')&&r.managerId!==data.user.id;if(r.status==='作废待确认')return can(approvePermission(r.kind));return r.status==='待审批'&&can(approvePermission(r.kind))}
// Q03: area completion requests and ledger reversals waiting for this user are listed with the records.
const recordTasks=computed(()=>scoped(data.records).filter(r=>reviewable(r)||(r.status==='待付款'&&can('expense:pay')&&!mine(r.createdBy))||(r.status==='会计待处理'&&can('fine:handle'))||(r.status==='待结算'&&can('payroll:pay'))||(r.status==='已退回'&&mine(r.createdBy))))
const areaTasks=computed(()=>can('work:complete')?scoped(data.areas).filter(canConfirmCompletion).map(a=>({taskType:'area',id:'area-'+a.id,title:a.name+' · 完工确认',author:a.completionRequester||'组长',date:a.completionRequestedAt,status:'待确认完工',amount:areaTotal(a)})):[])
const reversalTasks=computed(()=>scoped(data.transactions).filter(canReviewReversal).map(t=>({taskType:'reversal',id:'reversal-'+t.reversal.id,title:'冲正审批 · '+ledgerTitle(t),author:t.reversal.requester,date:String(t.reversal.requestedAt||'').slice(0,10),status:'冲正待审批',amount:t.amount,month:String(t.date).slice(0,7)})))
const tasks=computed(()=>[...recordTasks.value,...areaTasks.value,...reversalTasks.value])
function openTask(row){if(row.taskType==='area')navigate('projects');else if(row.taskType==='reversal'){month.value=row.month;navigate('ledger')}else showRecord(row)}
// V08: approved costs that are not paid yet (unpaid wage lines by month, reimbursements awaiting payment).
const unpaidCosts=computed(()=>{const months={};for(const p of scoped(data.payroll).filter(p=>!p.paid)){const m=months[p.month]||(months[p.month]={type:'工资',date:p.month,lines:0,amount:0});m.lines++;m.amount+=Number(p.amount||0)}return [...Object.values(months).sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(m=>({...m,title:m.date+' 待结算工资（'+m.lines+' 条）'})),...scoped(data.records).filter(r=>r.kind==='报销'&&r.status==='待付款').map(r=>({type:'报销',title:r.title+' · '+r.author,date:r.date,amount:Number(r.amount||0),record:r}))]}),unpaidTotal=computed(()=>unpaidCosts.value.reduce((s,c)=>s+c.amount,0))
const areaTotal=a=>a.total ?? (Number(a.contract||0)+Number(a.wages||0))
const workType=a=>a.status==='未开工'?'—':(a.type||'—')
// Q05: a designated leader submits for the whole area; otherwise each leader submits their own work.
const canRequestCompletion=a=>can('work:submit')&&a.status==='进行中'&&(!a.leaderId||mine(a.leaderId))
// Q04: completion is only confirmed from a pending request, never by its requester.
const canConfirmCompletion=a=>can('work:complete')&&!!a.completionRequestedAt&&!a.completedAt&&!mine(a.completionRequestedBy)
const attendance=computed(()=>scoped(data.attendance).filter(r=>String(r.date).slice(0,10)===attendanceDate.value)),attendanceWorkers=computed(()=>new Set(attendance.value.map(r=>r.workerId)).size)
const archiveStart=computed(()=>{const [y,m]=data.serverDate.split('-').map(Number);const d=new Date(y,m-3,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01'})
const archives=computed(()=>scoped(data.areas).filter(a=>a.completedAt&&(archiveRange.value==='all'||String(a.completedAt).slice(0,10)>=archiveStart.value)&&(!archiveMonth.value||String(a.completedAt).startsWith(archiveMonth.value))))
const payroll=computed(()=>scoped(data.payroll).filter(p=>p.month===month.value)),selectedLines=computed(()=>selected.value.filter(p=>!p.paid)),selectedTotal=computed(()=>selectedLines.value.reduce((s,p)=>s+p.amount,0)),selectedWorkers=computed(()=>new Set(selectedLines.value.map(p=>p.workerId)).size)
const batches=computed(()=>new Map((data.payrollBatches||[]).map(b=>[String(b.id),b]))),batchOf=row=>row.paymentId?batches.value.get(String(row.paymentId)):null
const transactions=computed(()=>scoped(data.transactions).filter(t=>t.date.startsWith(month.value))),income=computed(()=>transactions.value.filter(t=>t.amount>0).reduce((s,t)=>s+t.amount,0)),expense=computed(()=>-transactions.value.filter(t=>t.amount<0).reduce((s,t)=>s+t.amount,0)),balance=computed(()=>scoped(data.transactions).filter(t=>t.date.slice(0,7)<=month.value).reduce((s,t)=>s+t.amount,0))
const hasOpening=computed(()=>scoped(data.transactions).some(t=>t.source==='opening'&&t.reversal?.status!=='approved'))
const ledgerTitle=t=>t.source==='opening'?'期初余额':t.title
// Q15: who may request a reversal depends on the business that produced the entry.
const reversalPermissions={expense:'expense:pay',fine:'fine:handle',payroll:'payroll:pay',manual:'ledger:edit',opening:'ledger:edit'},reversalLabels={pending:'冲正待审批',approved:'已冲正',rejected:'冲正已驳回'}
const canRequestReversal=t=>!!reversalPermissions[t.source]&&can(reversalPermissions[t.source])&&!['pending','approved'].includes(t.reversal?.status)
const canReviewReversal=t=>t.reversal?.status==='pending'&&!!data.reversalReviewer&&!mine(t.reversal.requestedBy)
function voucherIds(t){if(t.files?.length)return t.files;if(t.source==='payroll'){const b=batches.value.get(String(t.sourceId));return b?.proof?[b.proof]:[]}if(t.source==='expense'){const r=data.records.find(r=>r.id===t.sourceId);return r?.proof?[r.proof]:[]}return []}
function showVouchers(t){voucherList.value=[...voucherIds(t)];voucherOpen.value=true}
function newRecord(type){editRecord.value=null;formKind.value=type}
function editApplication(item){detail.value=null;editRecord.value=item;formKind.value=item.kind}
function showRecord(row){detail.value=JSON.parse(JSON.stringify(row))}
function editMaster(type,value){master.value={type,value}}
async function refreshPage(){await refresh();await accountsPage.value?.reload()}
function toggleWorker(row){act(async()=>{const active=Number(row.active ?? 1)===1?0:1;await ElMessageBox.confirm(active?'确认恢复 '+row.name+'？恢复后可再次选择安排施工。':'确认停用 '+row.name+'？停用后不再出现在新申请人员列表，历史工资与单据保留。',active?'恢复人员':'停用人员');await write('/master/person',{...row,active},'PUT');ElMessage.success(active?'人员已恢复':'人员已停用')})}
function complete(row){act(async()=>{await ElMessageBox.confirm('确认 '+row.name+' 已施工完工（'+(row.completionRequester||'组长')+' 提交）？财务结算仍可继续处理。','施工完工');await write('/areas/'+row.id+'/complete',{});ElMessage.success('已归档')})}
function requestCompletion(row){act(async()=>{await ElMessageBox.confirm('确认 '+row.name+' 已完成施工，提交项目经理确认？确认前该区域暂停新增用工。','提交完工');await write('/areas/'+row.id+'/completion-request',{});ElMessage.success('已提交，等待项目经理确认')})}
function rejectCompletion(row){act(async()=>{const {value}=await ElMessageBox.prompt('请填写退回原因','退回完工申请',{inputValidator:v=>!!String(v||'').trim()&&String(v).trim().length<=200,inputErrorMessage:'请填写退回原因，不超过200字'});await write('/areas/'+row.id+'/completion-reject',{reason:String(value).trim()});ElMessage.success('已退回')})}
function reopen(row){act(async()=>{const {value}=await ElMessageBox.prompt('重新开工后区域恢复施工，可继续登记用工；完工历史保留在处理记录中。请填写原因','重新开工 · '+row.name,{inputPlaceholder:'重新开工原因，不超过200字',inputValidator:v=>!!String(v||'').trim()&&String(v).trim().length<=200,inputErrorMessage:'请填写重新开工原因，不超过200字'});await write('/areas/'+row.id+'/reopen',{reason:String(value).trim()});ElMessage.success('区域已重新开工')})}
let paymentRequest={fingerprint:'',key:''}
watch(payroll,rows=>{for(const row of selected.value)if(!rows.some(p=>p.id===row.id&&!p.paid))payrollTable.value?.toggleRowSelection(row,false)},{flush:'post'})
// Q12: wages are settled with the actual paid date, method and an uploaded voucher.
function settle(){if(!selectedLines.value.length||busy.value)return;if(!payment.value.date)payment.value={date:data.serverDate,method:payMethods[0],proof:''};settleOpen.value=true}
const uploadPayrollProof=e=>act(async()=>{const file=e.target.files[0];e.target.value='';if(file)payment.value.proof=await uploadImage(file)})
function confirmSettle(){act(async()=>{const selectedProject=projectId.value,selectedMonth=month.value,{date,method,proof}=payment.value;const lineIds=selectedLines.value.map(p=>p.id).sort((a,b)=>a-b);if(!lineIds.length)throw Error('请选择待结算的工资明细');if(!date||date>data.serverDate)throw Error('请选择实际支付日期，且不能晚于今天');if(!proof)throw Error('请上传支付凭证');const fingerprint=JSON.stringify([selectedProject,selectedMonth,lineIds]);if(paymentRequest.fingerprint!==fingerprint)paymentRequest={fingerprint,key:requestKey()};const amount=await write('/payroll/settle',{projectId:selectedProject,month:selectedMonth,lineIds,date,method,proof,requestKey:paymentRequest.key});selected.value=[];settleOpen.value=false;payment.value={};ElMessage.success('已登记工资 ¥'+money(amount))})}
async function addVouchers(e,list){const files=[...e.target.files];e.target.value='';if(uploading.value)return;uploading.value=true;try{for(const f of files){if(list.length>=6)throw Error('最多上传6张凭证');list.push(await uploadImage(f))}}catch(err){ElMessage.error(err.message)}finally{uploading.value=false}}
function openLedger(){entry.value={projectId:projectId.value,direction:'收入',title:'',amount:0,date:data.serverDate,note:'',files:[],requestKey:requestKey()};ledgerOpen.value=true}
function saveLedger(){act(async()=>{if(!entry.value.files?.length)throw Error('请上传收支凭证');await write('/ledger',{...entry.value,amount:Number(entry.value.amount)*(entry.value.direction==='支出'?-1:1)});ledgerOpen.value=false;ElMessage.success('收支已保存')})}
// Q11: one opening balance per project; a negative amount records an overdraft.
function openOpening(){opening.value={projectId:projectId.value,direction:'余额',amount:0,date:data.serverDate,note:'',files:[],requestKey:requestKey()};openingOpen.value=true}
function saveOpening(){act(async()=>{const o=opening.value;if(!(Number(o.amount)>0))throw Error('请填写期初金额');if(!o.date||o.date>data.serverDate)throw Error('请选择期初日期，且不能晚于今天');await write('/ledger/opening',{projectId:o.projectId,amount:Number(o.amount)*(o.direction==='透支'?-1:1),date:o.date,note:o.note,files:o.files,requestKey:o.requestKey});openingOpen.value=false;ElMessage.success('期初余额已登记')})}
function requestReversal(t){act(async()=>{const {value}=await ElMessageBox.prompt('冲正经负责人或管理员审批后生成反向流水，原流水保留，对应业务恢复为未付款。请填写冲正原因','申请冲正 · '+ledgerTitle(t)+' ¥'+money(Math.abs(t.amount)),{inputPlaceholder:'冲正原因，不超过500字',inputValidator:v=>!!String(v||'').trim()&&String(v).trim().length<=500,inputErrorMessage:'请填写冲正原因，不超过500字'});await write('/ledger/'+t.id+'/reversal',{reason:String(value).trim()});ElMessage.success('冲正申请已提交，等待审批')})}
function reviewReversal(t,accept){act(async()=>{const {value}=await ElMessageBox.prompt((accept?'同意后生成反向流水，对应业务恢复为未付款。':'驳回后原流水保持不变。')+'冲正原因：'+t.reversal.reason,(accept?'同意冲正':'驳回冲正')+' · '+ledgerTitle(t),{inputPlaceholder:accept?'审批意见（选填）':'驳回原因（必填）',inputValidator:v=>{const text=String(v||'').trim();return (accept||!!text)&&text.length<=500},inputErrorMessage:accept?'审批意见不超过500字':'请填写驳回原因，不超过500字'});await write('/ledger/reversals/'+t.reversal.id+'/review',{version:t.reversal.version,accept,opinion:String(value||'').trim()});ElMessage.success(accept?'已同意冲正':'已驳回冲正')})}
function markAllRead(){act(async()=>{try{for(const notice of data.notifications.filter(n=>!n.read)){await shipyardApi('/notices/'+notice.id+'/read','POST',{});notice.read=true}ElMessage.success('已全部标为已读')}finally{await refresh().catch(()=>ElMessage.warning('消息已更新，刷新失败，请重新加载'))}})}
function openNotice(n){act(async()=>{const item=await shipyardApi('/records/'+n.recordId);await write('/notices/'+n.id+'/read',{});showRecord(item)})}
function exportRecords(){exportCsv('申请与审批',[['单号','工程','区域','类型','申请人','日期','付款日期','金额','状态','说明','被罚人员','工号','班组','工资归属月','作废原因'],...records.value.map(r=>{const person=r.kind==='罚款'?(r.personSnapshot||data.people.find(p=>p.id===r.person)||{}):{};return [r.id,r.ship,r.area,r.kind,r.author,r.date,r.paidDate,r.amount,r.status,r.note,person.name,person.code,person.team,r.type==='包工'?(r.payrollMonth||String(r.start||'').slice(0,7)):'',r.voidReason]})])}
function exportAttendance(){exportCsv('每日出勤',[['日期','工程','区域','姓名','工号','班组','工时'],...attendance.value.map(r=>[attendanceDate.value,project.value?.name,data.areas.find(a=>String(a.id)===String(r.areaId))?.name,r.name,r.code,r.team,r.hours])])}
function exportPayroll(){exportCsv('工资明细',[['工程','工作区域','月份','工人','类型','工时','时薪快照','倍率','金额','状态','付款批次','支付日期','支付方式'],...payroll.value.map(p=>{const b=batchOf(p);return [p.ship,p.area||'未记录工作区域',p.month,p.name,p.label,p.hours,p.rate,p.multiplier,p.amount,p.paid?'已结算':'待结算',p.paymentId,b?.paidDate,b?.method]})])}
function exportLedger(){exportCsv('收支台账',[['日期','工程','事项','收入','支出','备注','登记人','凭证数','冲正状态'],...transactions.value.map(t=>[t.date,t.ship,ledgerTitle(t),t.amount>0?t.amount:'',t.amount<0?-t.amount:'',t.note,t.creator,voucherIds(t).length,t.source==='reversal'?'冲正流水':t.reversal?reversalLabels[t.reversal.status]:''])])}
</script>
