.shipyard-dialog{--el-color-primary:#008c9d;--el-color-primary-light-3:#4aadb7;--el-color-primary-light-9:#e6f5f5;--el-border-radius-base:8px;color:#142c3c;font-family:'Microsoft YaHei',system-ui,sans-serif}
.shipyard-admin{--el-color-primary:#008c9d;--el-color-primary-light-3:#4aadb7;--el-color-primary-light-9:#e6f5f5;--el-border-radius-base:8px;padding:28px;color:#142c3c;background:#f4f7fa;min-height:calc(100vh - 84px);font-family:'Microsoft YaHei',system-ui,sans-serif}.shipyard-admin h1{font-size:27px;margin:5px 0 10px;font-weight:700}.shipyard-admin h2{font-size:18px;margin:0}.shipyard-admin h3{font-size:16px}.eyebrow{margin:0;font-size:12px;color:#008c9d;letter-spacing:2px}.subtitle{font-size:13px;color:#718498;margin:0}.subtitle span{margin-left:18px}.workspace-header{display:flex;align-items:center;justify-content:space-between;gap:20px}.workspace-controls{display:flex;gap:10px}.workspace-controls .el-select{width:210px}.workspace-nav{display:flex;flex-wrap:wrap;gap:6px;border-bottom:1px solid #dce6ec;margin:25px 0 22px;padding-bottom:12px}.workspace-nav button{border:0;background:transparent;border-radius:8px;color:#576f80;padding:10px 15px;font-size:14px;cursor:pointer}.workspace-nav button.active{background:#e0f1f1;color:#007e8c;font-weight:700}.workspace-nav button:hover{background:#e8eff3}.workspace-nav button:focus-visible{outline:2px solid #008c9d}.shipyard-admin>section,.shipyard-admin>template>section{background:#fff;border-radius:12px;padding:22px;border:1px solid #e5edf2}.table-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 20px}.el-table+.table-heading,.shipyard-admin .el-table+h2{margin-top:32px}.actions,.filters{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.filters{margin:18px 0}.filters .el-input{max-width:270px}.filters .el-select{max-width:180px}.filters .el-date-editor{max-width:180px}.hint{font-size:13px;color:#718498;line-height:1.7}.search{max-width:320px;margin-bottom:16px}.shipyard-admin .el-drawer{color:#142c3c}.shipyard-admin .el-drawer h3{margin-top:24px}.shipyard-admin .el-drawer .el-select{width:100%}.form-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.form-columns .el-date-editor{width:100%}.file-line{display:flex;align-items:center;justify-content:space-between;width:100%}.record-heading{display:flex;align-items:center;gap:20px;margin:10px 0 22px}.record-heading strong{font-size:28px}.action-row{display:flex;justify-content:flex-end;gap:12px;margin-top:18px}.shipyard-admin .el-alert{margin-bottom:18px}.shipyard-admin .el-table{border-radius:8px;--el-table-header-bg-color:#f1f6f8;--el-table-header-text-color:#486173}.shipyard-admin .el-table .cell{line-height:25px}.shipyard-admin .el-table th{font-weight:600}.shipyard-admin .el-descriptions__label{font-weight:500!important}.shipyard-admin input[type=file]{max-width:100%}.unpaid-costs{margin-top:16px}.unpaid-title{font-weight:600;color:#142c3c}@media(max-width:1000px){.shipyard-admin{padding:16px}.workspace-header{align-items:flex-start;flex-direction:column}.table-heading{align-items:flex-start;flex-direction:column}.workspace-nav button{padding:9px 10px}.workspace-controls{width:100%}.form-columns{grid-template-columns:1fr}}
</style>
